SELECT i.* FROM item i JOIN community c ON c.id = i.community_id WHERE i.deleted = 0 AND i.status = 'ON_SHELF'
AND (i.title LIKE CONCAT('%', #{q.keyword}, '%') OR i.description LIKE CONCAT('%', #{q.keyword}, '%'))
AND i.category_id IN
#{cid}
AND i.community_id = #{q.communityId}
AND i.daily_price >= #{q.minPrice}
AND i.daily_price <= #{q.maxPrice}
AND i.id NOT IN
#{eid}
ORDER BY
CASE WHEN i.community_id = #{myCommunityId} THEN 1 ELSE 0 END DESC,
CASE WHEN c.district = #{myDistrict} THEN 1 ELSE 0 END DESC,
i.rent_count DESC, i.created_at DESC, i.id DESC

SELECT DISTINCT o.item_id
FROM order_occupancy o
JOIN rental_order r ON r.id = o.order_id
WHERE r.status IN ('PENDING', 'CONFIRMED', 'IN_USE', 'OVERDUE')
  AND o.occupy_date >= #{from}
  AND o.occupy_date < #{to}

SELECT DISTINCT o.occupy_date
FROM order_occupancy o
JOIN rental_order r ON r.id = o.order_id
WHERE o.item_id = #{itemId}
  AND r.status IN ('PENDING', 'CONFIRMED', 'IN_USE', 'OVERDUE')
  AND o.occupy_date >= #{from}
  AND o.occupy_date < #{to}
ORDER BY o.occupy_date
